public class TypeTextStubProvider implements System.StubProvider {
    public Boolean providerFlag = true;
    public String providerName = 'synthetic';
    public static List<String> observedTypes = new List<String>();
    public Object handleMethodCall(Object receiver, String methodName,
            Type returnType, List<Type> parameterTypes,
            List<String> parameterNames, List<Object> arguments) {
        observedTypes.clear();
        observedTypes.add(returnType == null ? 'null' : returnType.getName());
        for (Type item : parameterTypes) observedTypes.add(item == null ? 'null' : item.getName());
        return null;
    }
}

